		assertThat(heartbeat.start(writer)).isTrue();
		assertThat(target.flushes.await(5, TimeUnit.SECONDS)).isTrue();
		TupleQueryResult result = new IteratingTupleQueryResult(List.of("value"), bindingSets);
		QueryResults.report(result, writer);
		heartbeat.complete();
		assertThat(target.flushCount.get()).isGreaterThanOrEqualTo(2);

		TupleQueryResultBuilder builder = new TupleQueryResultBuilder();
		TupleQueryResultParser parser = new SPARQLResultsJSONParserFactory().getParser();
		parser.setTupleQueryResultHandler(builder);
		parser.parse(new ByteArrayInputStream(target.toByteArray()));
		TupleQueryResult parsed = builder.getQueryResult();
		assertThat(parsed.hasNext()).isEqualTo(!bindingSets.isEmpty());
		parsed.close();
		heartbeat.close();
